// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, address target, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(target != address(0));
        vm.assume(amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(target, amount) { ok = true; } catch { ok = false; }
        bool isOwner = (caller == c.owner());
        assertTrue(ok == isOwner);
    }
}
